SELECT cs.cs_sold_date_sk, cs.cs_quantity, cs.cs_sales_price, cs.cs_ext_sales_price, cs.cs_ext_discount_amt, cs.cs_net_paid, sm.sm_ship_mode_id, sm.sm_type, CASE WHEN cs.cs_quantity > 23 THEN cs.cs_sales_price * cs.cs_quantity ELSE cs.cs_sales_price END AS adjusted_sales, (cs.cs_ext_sales_price - cs.cs_ext_discount_amt) * 1.1 AS final_price_with_tax, cs.cs_net_profit / NULLIF(cs.cs_quantity, 0) AS profit_per_item, CASE WHEN sm.sm_type = 'TWO DAY                       ' THEN 'NEXT DAY                      ' ELSE 'NEXT DAY                      ' END AS ship_type_category, concat(sm.sm_carrier, '-', sm.sm_code) AS carrier_code FROM catalog_sales cs JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk WHERE cs.cs_sold_date_sk = 2450818
